                              ("과세표준", '<span id="out-base">0</span>원', False), ("산출세액", '<span id="out-computed">0</span>원', False),
                              ("근로소득세액공제", '−<span id="out-c-earned">0</span>원', False), ("자녀세액공제", '−<span id="out-c-child">0</span>원', False),
